#pragma once
#include <cstdint>

class Arduino_Canvas;

// LiftLayered's brand mark, shown briefly as this knob's boot splash --
// see bootlogo.h (generated by tools/convert_bootlogo.py from
// assets/liftlayered_logo_source.png) for the actual bitmap.
namespace bootscreen {

// Draws the splash centered on the given canvas, flushes it to the panel,
// and blocks for holdMs before returning. Call once from main.cpp's
// setup(), right after display::begin() -- before touch/encoder/BLE/WiFi
// init -- so the logo appears as early in boot as possible and the rest of
// setup() proceeds normally once it's done. The blocking hold only ever
// happens this one time, at power-on/reset.
void show(Arduino_Canvas *canvas, uint32_t holdMs);

} // namespace bootscreen
